contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint before = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint afterAdd = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        bool withdrew;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        uint finalBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(withdrew || (finalBalance == afterAdd && finalBalance == before + amount));
    }
}

